    showStackedWildsGame(subGameresult){
        return new Promise(async (sucess,failed)=>{
            this._dingguang.active = true
            await cc.vv.gameData.getStackedWildsGame().showGame(subGameresult.wildCols,subGameresult.realCards,cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime())
            cc.vv.gameData.getStackedWildsGame().hideGame()
            this._dingguang.active = false
            sucess()
        })
    },

    showRandomWildsGame(subGameresult){
        return new Promise(async (sucess,failed)=>{
            this._slotsMask.active = true
            if(cc.vv.gameData.GetSlotsScript()._isInFree){
                this._slotsMask.height = 680
            }else{
                this._slotsMask.height = 340
            }
            await cc.vv.gameData.getRandomWildsGame().showGame(subGameresult.randIdxs,subGameresult.randCards)
            this._slotsMask.active = false
            cc.vv.gameData.getRandomWildsGame().hideGame()
            sucess()
        })
    },

    showJackPoolNorMalAction(){
        if(cc.vv.gameData){
            let PrizePoolRoot = this._PrizePoolRoot
            let cfg = cc.vv.gameData.getGameCfg()
            if(PrizePoolRoot){
                for (let i = 1; i < 6; i++) {
                    const element = jackpotNames[cfg.jackpotType[i]-1];
                    let targetJpNode = cc.find('prizePool_'+element,PrizePoolRoot)
                    let winEffect = cc.find("winEffect",targetJpNode)
                    winEffect.active = false
                    let iconNode = cc.find('icon_'+element,PrizePoolRoot)
                    let jackpotAwards = cc.find("jackpot_awards_01",iconNode)
                    jackpotAwards.scale = 1
                    let jackpotAwardsSp = jackpotAwards.getComponent(sp.Skeleton)
                    jackpotAwardsSp.setAnimation(0,"animation"+(6-i)+"_4",true)
                    cc.tween(jackpotAwards).delay(i*0.5)
                    .to(0.5,{scale:0},{easing:"backIn"})
                    .delay((5-i)*1+3)
                    .to(0.5,{scale:1},{easing:"backOut"}).start()
                }
            }
        }
    },

    showWinJackPoolAnimation(index){
        let PrizePoolRoot = this._PrizePoolRoot
        if(PrizePoolRoot){
            const element = jackpotNames[index];
            let iconNode = cc.find('icon_'+element,PrizePoolRoot)
            let jackpotAwards = cc.find("jackpot_awards_01",iconNode)
            jackpotAwards.scale = 1
            jackpotAwards.stopAllActions()
            let jackpotAwardsSp = jackpotAwards.getComponent(sp.Skeleton)
            jackpotAwardsSp.setAnimation(0,"animation"+(5-index)+"_1",false)
            jackpotAwardsSp.addAnimation(0,"animation"+(5-index)+"_2",false)
            jackpotAwardsSp.addAnimation(0,"animation"+(5-index)+"_3",false)
            let targetJpNode = cc.find('prizePool_'+element,PrizePoolRoot)
            let winEffect = cc.find("winEffect",targetJpNode)
            winEffect.active = true
        }
    },

    setFreeGame(bFree){
        return new Promise(async (sucess,failed)=>{
            if(bFree){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition2)
                let qiePinSp = this._qiePin[0].getComponent(sp.Skeleton)
                this._qiePin[0].active = true
                qiePinSp.setAnimation(0,"animation",false)
                qiePinSp.setCompleteListener(()=>{
                    this._qiePin[0].active = false
                    qiePinSp.setCompleteListener(null)
                })
                await this.awaitTime(2.5)
                await cc.vv.gameData.GetSlotsScript().showFreeGameSlots()
            }else{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition1)
                this.showExitFree()
                await cc.vv.gameData.GetSlotsScript().hideFreeGameSlots()
            }
            sucess()
        })
    },

