    async showJackInTheBoxWin(){
        if(cc.vv.gameData.GetSlotsScript()._isInFree){ //在免费游戏中不能修改押注
            return
        }
        if(cc.vv.gameData.GetSlotState() != 'idle'){
            return
        }
        if(cc.vv.gameData.GetAutoModelTime() > 0){
            return
        }
        let collectButton = cc.find("iconRight/button",this._turntableTriggerBar)
        collectButton.getComponent(cc.Button).interactable = false
        await cc.vv.gameData.getJackInTheBox().showPopWin(cc.vv.gameData.getBonusGame())
        collectButton.getComponent(cc.Button).interactable = true
    },

    unlockTurntable(){
        if(cc.vv.gameData.GetSlotsScript()._isInFree){ //在免费游戏中不能修改押注
            return
        }
        if(cc.vv.gameData.GetSlotState() != 'idle'){
            return
        }
        if(cc.vv.gameData.GetAutoModelTime() > 0){
            return
        }
        let turntableBarButton = cc.find("lock/button",this._turntableTriggerBar)
        let bonusGame = cc.vv.gameData.getBonusGame()
        if(bonusGame){
            if(bonusGame.needBet <= cc.vv.gameData._deskInfo.mults.length){
                turntableBarButton.getComponent(cc.Button).instantiate = false
                let bottom = cc.vv.gameData.GetBottomScript()
                bottom.SetBetIdx(bonusGame.needBet)
            }
        }
    },

