/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        _backResult:[],
        _tempBackResult:[],
        _backType:null,
        _backNum:0,
        _bgholderNode:null,
        _symbolsBg:[],
        _symbolBgTemplete:null,
        _curBgType:3,  //随机背景的类型
        _curBgNum:0,   //当前随机背景的索引
        _curSymbolId:0,  //当前随机symbolId
        _curSymbolNum:0,  //需要设置的个数
        _showJackpotJl:false,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._super()

        this._bgholderNode = cc.find("mask/holderBg",this.node)
        if(!this._symbolBgTemplete){
            let cfg = cc.vv.gameData.getGameCfg()
            this._symbolBgTemplete = cc.vv.gameData.GetPrefabByName(cfg.symbolBgPrefab)
        }
    },

    start () {

    },

    randomBg(){
        if(this._curBgType === 3){
            if(this._reelIdx === 4){
                let ret = Global.random(1,100)
                if(ret >50){
                    this._curBgType = 3
                }else{
                    this._curBgType = Global.random(1,3)
                }
            }else{
                let ret = Global.random(1,100)
                this._curBgType = ret > 80?1:3
            }
            
            if(this._curBgType !== 3){
                this._curBgNum = 1
            }
        }
    },

    createBg(symbol){
        if(this._curBgType !== 3 && this._curBgNum <= 4){
            if(this._curBgType === 1){
                symbol.SetBackground("yellow"+(5-this._curBgNum))
            }else if(this._curBgType === 2){
                symbol.SetBackground("qiqiu"+(5-this._curBgNum))
            }
            this._curBgNum++
            if(this._curBgNum > 4){
                this._curBgType = 3
            }
        }else{
            symbol.SetBackground("")
        }
    },

    randomSymbol(){
        if(this._curSymbolNum <= 0){
            let cfg = cc.vv.gameData.getGameCfg()
            let randIdx = Global.random(1,cfg.randomSymbols.length)
            this._curSymbolId = cfg.randomSymbols[randIdx-1]
            this._curSymbolNum = 4
        }
    },

    setSymbol(symbol){
        symbol.ShowById(this._curSymbolId)
        this._curSymbolNum--
    },

    LoadSymbols:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let url = cfg.symbolPrefab

        if(!this._symbolTemplete){
            this._symbolTemplete = cc.vv.gameData.GetPrefabByName(url)
            
        }
        for(let i = 0; i < this._nCount+1; i++){
            this.CreateOneSymbol()
        }
        this.ReLayOut()
        
    },

    //创建一个符号元素
    CreateOneSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let node = cc.instantiate(this._symbolTemplete)
        node.parent = this._holderNode
        let bgNode = cc.instantiate(this._symbolBgTemplete)
        bgNode.parent = this._bgholderNode
        let scp = node.addComponent(cfg.scripts.Symbols)
        let idx = this._symbols.length; //行号
        scp.Init(idx,this._topAniNode,bgNode)
        scp.SetSymbolReelIdx(this._reelIdx)
        this._symbols.push(scp)
        this._symbolsBg.push(bgNode)
        this.randomBg()
        this.randomSymbol()
        this.setSymbol(scp)
        this.createBg(scp)
    },

    //符号重排设置位置
    ReLayOut:function(){
        for (let i = 0; i < this._symbols.length; i++) {
            let element = this._symbols[i];
            element.node.position = this.GetSymbolPosByRow(i)
            element._bindBg.position = element.node.position
            element.SetSymbolIdx(i);
        }
    },

    recaveryReel(){
        for (let i = 0; i < this._symbols.length; i++) {
            const symbol = this._symbols[i];
            let ret = this._result.shift()
            if(ret){
                let sid = ret.sid
                let data = null
                let bgName = this._tempBackResult.shift()
                if(sid){
                    symbol.ShowById(sid,data)
                    symbol.SetBackground(bgName)
                }
            }
        }
    },

    //重写
    //显示免费游戏加速效果
    //加速框的显示
    ShowAntiEffect:function(bShow,name){
        if (bShow == false) {
            let cfg = cc.vv.gameData.getGameCfg()
            if (cfg.reelStateInfo) {
                for (let info of cfg.reelStateInfo) {
                    let node = cc.find(info.antiNode,this.node)
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }
                    }
                }
            }
        }else{
            let node = cc.find(name,this.node)
            if(node){
                node.active = bShow
            }
            else{
                cc.log("未找到加速节点：node_anti");
            }
        }
    },

    ShowJackpotJlEffect:function(bShow){
        if (bShow) {
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.anticipation2)
        }else{
            Global.SlotsSoundMgr.stopEffectByName(Global.SlotsSoundMgr.anticipation2)
        }
        let node = cc.find("jackpot_jl",this.node)
        if(node){
            node.active = bShow
        }
        else{
            cc.log("未找到加速节点：jackpot_jl");
        }
    },

    /**
     * 判断一个数组连续几个是否相等
     * @param {Array} arr 数组
     * @param {number} start 开始位置
     * @param {number} num 数量
     */
    checkArrVal(arr,start,num){
        let val = arr[start].type
        for (let i = start; i < num; i++) {
            const element = arr[i].type;
            if(element !== val){
                return false
            }
        }
        return true
    },

    SetBackResult(backResult){
        let tempResull = []
        let index = 0
        while(index < backResult.length){
            const element = backResult[index].type;
            if(element === 1){
                if(this.checkArrVal(backResult,index,4)){  //4个连在一起
                    tempResull[tempResull.length] = "yellow4"
                    tempResull[tempResull.length] = "yellow3"
                    tempResull[tempResull.length] = "yellow2"
                    tempResull[tempResull.length] = "yellow1"
                    index += 4
                }else if(this.checkArrVal(backResult,index,3)){  //三个连在一起，这里只可能出现在上边缘和下边缘
                    if(backResult[index - 1]){ //当前位置后一个位置有值表示这是上边缘
                        tempResull[tempResull.length] = "yellow4"
                        tempResull[tempResull.length] = "yellow3"
                        tempResull[tempResull.length] = "yellow2"
                    }else{  //下边缘
                        tempResull[tempResull.length] = "yellow3"
                        tempResull[tempResull.length] = "yellow2"
                        tempResull[tempResull.length] = "yellow1"
                    }
                    index += 3
                }else if(this.checkArrVal(backResult,index,2)){//两个连在一起，这里只可能出现在上边缘和下边缘
                    if(backResult[index - 1]){ //当前位置后一个位置有值表示这是上边缘
                        tempResull[tempResull.length] = "yellow4"
                        tempResull[tempResull.length] = "yellow3"
                    }else{  //下边缘
                        tempResull[tempResull.length] = "yellow2"
                        tempResull[tempResull.length] = "yellow1"
                    }
                    index += 2
                }else{
                    if(backResult[index - 1]){ //当前位置后一个位置有值表示这是上边缘
                        tempResull[tempResull.length] = "yellow4"
                    }else{  //下边缘
                        tempResull[tempResull.length] = "yellow1"
                    }
                    index++
                }
            }else if(element === 2){
                if(this.checkArrVal(backResult,index,4)){  //4个连在一起
                    tempResull[tempResull.length] = "qiqiu4"
                    tempResull[tempResull.length] = "qiqiu3"
                    tempResull[tempResull.length] = "qiqiu2"
                    tempResull[tempResull.length] = "qiqiu1"
                    index += 4
                }else if(this.checkArrVal(backResult,index,3)){  //三个连在一起，这里只可能出现在上边缘和下边缘
                    if(backResult[index - 1]){ //当前位置后一个位置有值表示这是上边缘
                        tempResull[tempResull.length] = "qiqiu4"
                        tempResull[tempResull.length] = "qiqiu3"
                        tempResull[tempResull.length] = "qiqiu2"
                    }else{  //下边缘
                        tempResull[tempResull.length] = "qiqiu3"
                        tempResull[tempResull.length] = "qiqiu2"
                        tempResull[tempResull.length] = "qiqiu1"
                    }
                    index += 3
                }else if(this.checkArrVal(backResult,index,2)){//两个连在一起，这里只可能出现在上边缘和下边缘
                    if(backResult[index - 1]){ //当前位置后一个位置有值表示这是上边缘
                        tempResull[tempResull.length] = "qiqiu4"
                        tempResull[tempResull.length] = "qiqiu3"
                    }else{  //下边缘
                        tempResull[tempResull.length] = "qiqiu2"
                        tempResull[tempResull.length] = "qiqiu1"
                    }
                    index += 2
                }else{
                    if(backResult[index - 1]){ //当前位置后一个位置有值表示这是上边缘
                        tempResull[tempResull.length] = "qiqiu4"
                    }else{  //下边缘
                        tempResull[tempResull.length] = "qiqiu1"
                    }
                    index++
                }
            }else{
                tempResull[tempResull.length] = "null"
                index++
            }
        }
        this._backResult = tempResull
        this._tempBackResult = Global.copy(this._backResult)
        const element = backResult[backResult.length - 1].type;
        if(element === 3){
            this._curBgType = 3
        }else{
            if(backResult[backResult.length - 4] && backResult[backResult.length - 4].type === element){
                this._curBgType = 3
            }else if(backResult[backResult.length - 3] && backResult[backResult.length - 3].type === element){
                this._curBgType = element
                this._curBgNum = 3
            }else if(backResult[backResult.length - 2] && backResult[backResult.length - 2].type === element){
                this._curBgType = element
                this._curBgNum = 2
            }else{
                this._curBgType = element
                this._curBgNum = 1  
            }
        }
    },

    //更新位置
    UpdatePosition:function(dt){
        this._stopTime = this._stopTime - dt
        this._curY += dt*this._speed
        if(this._curY > this._offset){
            this.updataSymbol()
        }else{
            this._holderNode.y = this._holderOrigPosY - this._curY
            this._bgholderNode.y = this._holderNode.y
        }
    },

    //重写
    updataSymbol(){
        let symbol = this._symbols.shift()
        let symbolData = null
        let bgName = null
        if(this._stopTime <= 0 && this._bStoping && this._result && !this._bResizing) {
            //开始设置结果
            this.ReadyToStop()
            if(this._result.shift){
                symbolData = this._result.shift()
            }
            if(this._tempBackResult.shift){
                bgName = this._tempBackResult.shift()
            }
            symbol.SetBackground(bgName)
            if(!symbolData){
                this._bMoving = false
            }
        }
        if (!symbolData) {
            this.randomBg()
            this.randomSymbol()
            this.setSymbol(symbol)
            this.createBg(symbol)
        }else{
            symbol.ShowById(symbolData.sid,symbolData.data)
        }
        this._symbols.push(symbol)
        this.ReLayOut()
        this._curY = 0
        this._holderNode.y = this._holderOrigPosY
        this._bgholderNode.y = this._holderNode.y
        if(!this._bMoving){
            this.OnReelBounsAction()
            this.OnReelBounsBgAction()
        }
    },

    //列背景回弹
    OnReelBounsBgAction:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let distance = cfg.bounceInfo ? cfg.bounceInfo.distance : 30
        let time = cfg.bounceInfo ? cfg.bounceInfo.time : 0.3
        cc.tween(this._bgholderNode)
        .to(distance/this._speed,{position:cc.v2(this._bgholderNode.x,this._holderOrigPosY - distance)})
        .to(time,{position:cc.v2(this._bgholderNode.x,this._holderOrigPosY)})
        .start()
    },

    //重写
    //回弹动作最低点
    OnReelBounsActionDeep:function(){
        this.ShowAntiEffect(false)
        this.ShowJackpotJlEffect(false)
        let slots = cc.vv.gameData.GetSlotsScript()
        slots.OnReelBounsActionDeep(this._reelIdx)
        for(let i = 0; i < this._originResult.length; i++){
            this._symbols[i].StopMoveDeep();
        }
    },

    //重写
    //列回弹动作完成之后
    OnReelBounsActionEnd:function(){
        this.playReelStop()
        let slots = cc.vv.gameData.GetSlotsScript()
        slots.OnReelBounsActionEnd(this._reelIdx)
        //这里有个比较难实现的需求，symbol在滚动的过程中需要覆盖左右两边，按现在的设计，很难做到，先做成停止的时候覆盖左右。
        //如果之前播放过停止动画就不需要停止的时候将symbol移动到顶层
        let playStopAni = false
        for (let info of this._reelState) {
            if (info.isStop){
                playStopAni = true
            }
        }
        for(let i = 0; i < this._originResult.length; i++){
            if(!playStopAni){
                this._symbols[i].StopMoveEnd();
            }
        }
        this.OnReelSpinEnd()
    },

    //重写
    StartRecycleSymbol:function(){
        //此游戏没用到回收卷轴的功能，免费游戏和普通游戏分别配置了一个row，调用此接口反而会导致免费游戏卷轴被错误回收
        //故此注销这个接口的调用
        // let cfg = cc.vv.gameData.getGameCfg()
        // if(this._symbols.length > (cfg.row+1)){
        //     let nCount = -(this._symbols.length -(cfg.row+1))
        //     this.AddCount(nCount)
        // }
    },

    //立即停止
    StopMoveRightNow:function(){
        this._stopRightNow = true

        if(this._bMoving && this._originResult && this._backResult) {
            this._result = Global.copy(this._originResult) 
            this._tempBackResult = Global.copy(this._backResult)
            for(let i = 0; i < this._symbols.length; i++){
                this.updataSymbol()
            }
        }
       
    },


    // update (dt) {},
});
