//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html
cc.Class({
    extends: cc.Component,

    properties: {
        jinkuang:{
            default:[],
            type:[cc.Node],
        },
        _jinKuangStartY:0,
    },

    onLoad(){
        this._jinKuangStartY = this.jinkuang[0].y
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showGame(finalPositon,jackpotType,result){
        return new Promise(async (sucess,falied)=>{
            this.node.active = true
            for (const iterator of this.jinkuang) {
                iterator.active = false
            }
            for (let i = 0; i < finalPositon.length; i++) {
                this.jinkuang[i].y = this._jinKuangStartY
                let zhongjiang = cc.find("jpzhongjiang",this.jinkuang[i])
                zhongjiang.active = false
                let effect = cc.find("effect",this.jinkuang[i])
                effect.active = false
                let node = cc.find("node",this.jinkuang[i])
                node.active = true
                let jackpot_zjlx_01 = cc.find("jackpot_zjlx_01",this.jinkuang[i])
                jackpot_zjlx_01.active = false
                let luodi = cc.find("jinkuangluodi",this.jinkuang[i])
                luodi.active = true
                this.jinkuang[i].active = true
                let time = (this.jinkuang[i].y + Math.abs(finalPositon[i].y))/(this.jinkuang[i].y + 1208)*2
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_full)
                cc.tween(this.jinkuang[i]).to(time,{position:cc.v3(this.jinkuang[i].x,finalPositon[i].y,0)}).start()
                await this.awaitTime(time)
                if(time < 2){
                    Global.SlotsSoundMgr.stopEffectByName(Global.SlotsSoundMgr.jp_full)
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jackpot_notify)
                    this.showEndAni(i,result[finalPositon.length - 1 - i])
                    await this.awaitTime(2-time)
                }
            }
            this.showJacakpotType(jackpotType)
            await this.awaitTime(2)
            sucess()
        })
    },

    showJackPotResult(finalPositon,jackpotType){
        return new Promise(async (sucess,falied)=>{
            let type = cc.vv.gameData.getGameCfg().jackpotType[jackpotType]
            this.node.active = true
            for (const iterator of this.jinkuang) {
                iterator.active = false
            }
            for (let i = 0; i < finalPositon.length; i++) {
                if(finalPositon[i].y > -1208){
                    let zhongjiang = cc.find("jpzhongjiang",this.jinkuang[i])
                    zhongjiang.active = false
                    let effect = cc.find("effect",this.jinkuang[i])
                    effect.active = false
                    let node = cc.find("node",this.jinkuang[i])
                    node.active = false
                    let jackpot_zjlx_01 = cc.find("jackpot_zjlx_01",this.jinkuang[i])
                    jackpot_zjlx_01.active = false
                    this.jinkuang[i].active = true
                    this.jinkuang[i].y = finalPositon[i].y
                }else{
                    this.jinkuang[i].active = false
                }
            }
            this.showJacakpotType(type)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell)
            cc.vv.gameData.getManage().showCaiDan()
            await this.awaitTime(2)
            sucess()
        })
    },

    showEndAni(i,backgrounds){
        let node = cc.find("node",this.jinkuang[i])
        node.active = false
        let luodi = cc.find("jinkuangluodi",this.jinkuang[i])
        let luodiSp = luodi.getComponent(sp.Skeleton)
        luodiSp.setAnimation(0,"animation1",false)
        luodiSp.setCompleteListener(()=>{
            if(backgrounds){
                for (let i = 0; i < backgrounds.length; i++) {
                    const idx = backgrounds[i];
                    let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                    if(symbol){
                        symbol.SetBackground("yellow"+(4-i))
                    }
                }
            }
            luodi.active = false
            luodiSp.setCompleteListener(null)
        })
        // luodiSp.addAnimation(0,"animation2",true)
        let effect = cc.find("effect",this.jinkuang[i])
        effect.active = true
        let effectSp = effect.getComponent(sp.Skeleton)
        effectSp.setAnimation(0,"animation1_1",false)
    },

    showJacakpotType(type){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.win_jackpot)
        cc.vv.gameData.getManage().showWinJackPoolAnimation(type-1)
        for (let i = 0; i < this.jinkuang.length; i++) {
            const element = this.jinkuang[i];
            let zhongjiang = cc.find("jpzhongjiang",element)
            zhongjiang.active = true
            let zhongjiangSp = zhongjiang.getComponent(sp.Skeleton)
            zhongjiangSp.setAnimation(0,"animation"+(6-type),true)
            let jackpot_zjlx_01 = cc.find("jackpot_zjlx_01",this.jinkuang[i])
            jackpot_zjlx_01.active = true
            zhongjiang.scale = 0.2
            cc.tween(zhongjiang).to(0.4,{scale:1.1}).to(0.1,{scale:1}).start()
            let luodi = cc.find("jinkuangluodi",this.jinkuang[i])
            luodi.active = true
            let luodiSp = luodi.getComponent(sp.Skeleton)
            luodiSp.setAnimation(0,"animation2",true)
        }
    },

    hideGame(){
        this.node.active = false
    },

    // update (dt) {},
});
