/**
 * 墨西哥帅哥，奖池
 */
let jackpotNames = ['Mini','Minor','Major','Grand','MAXI']  //节点名称
cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {
        _nowUpdatePool:0,  //当前更新的pool节点
    },

    
    //各个节点上的解锁/锁定表现
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){
        let jpNodeName = jackpotNames[poolType]
        this.updataJackPoolLock(poolType,bLock)
        let type = cc.vv.gameData.getGameCfg().jackpotType[poolType+1] - 1
        if(jpNodeName){
            let safeNode = cc.find('Canvas/safe_node')
            let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
            if(jpNode){
                let targetJpNode = cc.find('prizePool_'+jpNodeName,jpNode.node.parent)
                let iconNode = cc.find('icon_'+jpNodeName,jpNode.node.parent)
                if(targetJpNode && iconNode){
                    let lock_node = iconNode.getChildByName('lockbg')
                    let lockEffect = cc.find("lockEffect",targetJpNode)
                    let lockEffectSp = lockEffect.getComponent(sp.Skeleton)
                    if(lock_node){
                        if(bLock){
                            lock_node.active = true
                            if(!bInit){
                                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_lock)
                                lockEffectSp.setAnimation(0,"animation"+(5-type)+"_1",false)
                                lockEffectSp.addAnimation(0,"animation"+(5-type)+"_2",true)
                            }else{
                                lockEffectSp.setAnimation(0,"animation"+(5-type)+"_2",true)
                            }
                        }
                        else{
                            lock_node.active = false
                            if(!bInit){
                                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_unlock)
                                lockEffectSp.setAnimation(0,"animation"+(5-type)+"_3",false)
                            }else{
                                lockEffectSp.setAnimation(0,"animation"+(5-type)+"_1",false)
                                lockEffectSp.clearTracks()
                            }
                        }
                    }
                }
            }
        }
    },

    updataJackPoolLock(index,isLock){
        let tempIndex = cc.vv.gameData.getGameCfg().jackpotType[index+1] - 1
        if(isLock){
            if(this._nowUpdatePool < tempIndex){
                return
            }
            this._nowUpdatePool = tempIndex
        }else{
            if(this._nowUpdatePool > tempIndex){
                return
            }
            this._nowUpdatePool = tempIndex
        }
        let safeNode = cc.find('Canvas/safe_node')
        let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
        if(jpNode){
            for (let i = 0; i < jackpotNames.length; i++) {
                const jpNodeName = jackpotNames[i];
                let iconNode = cc.find('icon_'+jpNodeName,jpNode.node.parent)
                if(iconNode){
                    let lock_node = iconNode.getChildByName('lockbg')
                    let tips = cc.find("tips",iconNode)
                    if(lock_node){
                        if(index === i){
                            if(isLock){
                                lock_node.active = true
                                cc.find("lock",tips).active = true
                                cc.find("unlock",tips).active = false
                                tips.scale = 0
                                cc.tween(tips)
                                .to(0.5,{scale:1},{easing:"backOut"})
                                .delay(0.5)
                                .to(0.5,{scale:0},{easing:"backIn"}).start()
                            }
                            else{
                                lock_node.active = false
                                cc.find("lock",tips).active = false
                                cc.find("unlock",tips).active = true
                                tips.scale = 0
                                cc.tween(tips)
                                .to(0.5,{scale:1},{easing:"backOut"})
                                .delay(0.5)
                                .to(0.5,{scale:0},{easing:"backIn"}).start()
                            }
                        }else{
                            tips.stopAllActions()
                            tips.scale = 0
                        }
                    }
                }
            }
        }
    },
    // update (dt) {},
});
