// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html
cc.Class({
    extends: cc.Component,

    properties: {
        wildList:{
            default:[],
            type:[cc.Node],
        },
        _wildListStartY:0,
        _result:null,  //随机之后的卷轴
        _isFreeGame:false,
    },

    onLoad(){
        this._wildListStartY = this.wildList[0].y
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showGame(wildCols,realCards,isFreeGame){
        return new Promise(async (sucess,falied)=>{
            this.node.active = true
            this._result = cc.vv.gameData.GetSlotsScript().changeCardsArr(realCards)
            this._isFreeGame = isFreeGame
            for (const iterator of this.wildList) {
                iterator.active = false
            }
            let cfg = cc.vv.gameData.getGameCfg()
            let reels = cc.vv.gameData.GetSlotsScript()._reels
            let reel = reels[0]
            let symbol = reel._symbols[0]
            let position = symbol.node.convertToWorldSpaceAR(cc.v2(0,0-cfg.symbolSize.height/2))
            let finalPosition = cc.vv.gameData.getStackedWildsGame().node.convertToNodeSpaceAR(position)
            for (let i = 0; i < this.wildList.length; i++) {
                const wild = this.wildList[i]
                wild.active = true
                wild.y = this._wildListStartY
                let node = cc.find("wildluodi",wild)
                node.active = true
                let nodeSp = node.getComponent(sp.Skeleton)
                if(this._isFreeGame){
                    nodeSp.setAnimation(0,"animation2_1",true)
                }else{
                    nodeSp.setAnimation(0,"animation1_1",true)
                }
                let time = 2
                let finalY = 0
                if(this.findIsWild(wildCols,i)){
                    time = (wild.y + Math.abs(finalPosition.y))/(wild.y + 1428)*2
                    finalY = finalPosition.y
                }else{
                    finalY = -1428
                }
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wild_full)
                cc.tween(wild).to(time,{position:cc.v3(wild.x,finalY,0)}).start()
                await this.awaitTime(time)
                if(time < 2){
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wild_notify)
                    this.showEndAni(i)
                    this.changeSymbol(this._result[4-i],4-i)
                    await this.awaitTime(2-time)
                }
            }
            await this.awaitTime(1)
            sucess()
        })
    },

    findIsWild(wildCols,col){
        let relCol = 5 - col
        for (let i = 0; i < wildCols.length; i++) {
            const element = wildCols[i];
            if(relCol === element){
                return true
            }
        }
        return false
    },

    showEndAni(i){
        let node = cc.find("wildluodi",this.wildList[i])
        let nodeSp = node.getComponent(sp.Skeleton)
        if(this._isFreeGame){
            nodeSp.setAnimation(0,"animation2",false)
        }else{
            nodeSp.setAnimation(0,"animation1",false)
        }
        nodeSp.setCompleteListener(()=>{
            node.active = false
            nodeSp.setCompleteListener(null)
        })
    },

    changeSymbol(wildList,col){
        let reels = cc.vv.gameData.GetSlotsScript()._reels
        let reel = reels[col]
        for (let i = 0; i < reel._symbols.length; i++) {
            const symbol = reel._symbols[i];
            symbol.ShowById(wildList[i])
        }
    },

    hideGame(){
        this.node.active = false
    },

    // update (dt) {},
});
