cc.Class({
    extends: cc.Component,

    properties: {
        wild:{
            default:null,
            type:cc.Node,
        },
        _wildStartY:0,
        _result:null,  
        _wildList:[],
    },

    onLoad(){
        this._wildStartY = this.wild.y
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showGame(randIdxs,randCards){
        return new Promise(async (sucess,falied)=>{
            this.node.active = true
            for (let i = 0; i < this._wildList.length; i++) {
                const element = this._wildList[i];
                element.parent = null
            }
            let cfg = cc.vv.gameData.getGameCfg()
            let slotsScript = cc.vv.gameData.GetSlotsScript()
            for (let i = 0; i < randIdxs.length; i++) {
                const element = randIdxs[i];
                let symbol = slotsScript.GetSymbolByIdx(element)
                let position = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                let finalPosition = cc.vv.gameData.getRandomWildsGame().node.convertToNodeSpaceAR(position)
                let tempWild = cc.instantiate(this.wild)
                this._wildList.push(tempWild)
                tempWild.active = true
                tempWild.x = finalPosition.x
                tempWild.y = this._wildStartY
                tempWild.parent = this.node
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wild_appear)
                cc.tween(tempWild).to(1,{position:finalPosition}).start()
                await this.awaitTime(1)
                this.showEndAni(tempWild,randCards[i])
                symbol.ShowById(randCards[i])
            }
            await this.awaitTime(1)
            sucess()
        })
    },

    showEndAni(wild,destIdx){
        let wildtuoweiNode = cc.find("wildtuowei",wild)
        wildtuoweiNode.active = false
        let wildNode = cc.find("wild",wild)
        wildNode.active = true
        switch (destIdx) {
            case 2:{
                let wildShow = cc.find("wild",wildNode)
                if(wildShow){
                    wildShow.active = true
                }
            }break;
            case 3:{
                let wildShow = cc.find("wild2",wildNode)
                if(wildShow){
                    wildShow.active = true
                }
            }break;
            case 4:{
                let wildShow = cc.find("wild3",wildNode)
                if(wildShow){
                    wildShow.active = true
                }
            }break;
        }
        let node = cc.find("bouns",wild)
        node.active = true
        let nodeSp = node.getComponent(sp.Skeleton)
        nodeSp.setAnimation(0,"animation",false)
        nodeSp.setCompleteListener(()=>{
            nodeSp.setCompleteListener(null)
            node.active = false
        })
    },

    hideGame(){
        this.node.active = false
    },

    // update (dt) {},
});
