cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    InitCommComponent:function(){
        this._super()
        //manage
        let script = this.node.addComponent("Clown_Manage")
        //存到gamedata里面
        cc.vv.gameData.setManage(script)

        let safeNode = cc.find('Canvas/safe_node')
        let jackpotReelGame = safeNode.getComponentInChildren("Clown_JackpotReelGame")
        if(jackpotReelGame){
            cc.vv.gameData.setJackpotReelGame(jackpotReelGame)
        }
        let stackedWildsGame = safeNode.getComponentInChildren("Clown_stackedWildsGame")
        if(stackedWildsGame){
            cc.vv.gameData.setStackedWildsGame(stackedWildsGame)
        }
        let randomWildsGame = safeNode.getComponentInChildren("Clown_RandomWildsGame")
        if(randomWildsGame){
            cc.vv.gameData.setRandomWildsGame(randomWildsGame)
        }
        let jackInTheBox = safeNode.getComponentInChildren("Clown_jackInTheBox")
        if(jackInTheBox){
            cc.vv.gameData.setJackInTheBox(jackInTheBox)
        }
    },

    // update (dt) {},
});
