/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _bindBg:null,  //绑定的背景节点
        _bgNode:null,   //普通节点通用背景
        _bgResultNode:null,   //结果中服务器传过来的背景
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //idx:符号的序号，即在reel中的序号，0开始
    Init:function(idx,node,bgNode){
        this._topAniNode = node
        this._bindBg = bgNode
        this.SetSymbolIdx(idx);
    },

    //重写
    SetSymbolIdx:function(idx){
        this._symbolIdx = idx;
        if(this._id === 1){
            this.node.zIndex = 150 - idx;
        }else{
            this.node.zIndex = 100 - idx;
        }
    },

    //重写
    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id,data){
        this._id = id
        this._data = data
        
        this.setAnimationToTop(false)
        if(this._showNode){
            this._showNode.active = false
        }
        if(this._bgNode){
            this._bgNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].node){
            this._showNode = cc.find(cfg.symbol[id].node,this.node)
            this._showNode.active = true
            if(cfg.symbol[id].bg){
                this._bgNode = cc.find(cfg.symbol[id].bg,this._bindBg)
                this._bgNode.active = true
            }
        }
        else{
            console.log("未找到配置id:" + id)
        }
    },

    SetBackground(name){
        if(this._bgResultNode){
            this._bgResultNode.active = false
        }
        if(name && this._bindBg){
            this._bgResultNode = cc.find(name,this._bindBg)
            if(this._bgResultNode){
                this._bgResultNode.active = true
            }
        }
    },

    setSymbolShow(isVisible){
        this.node.active = isVisible
    },

    setSymbolBgShow(isVisible){
        this._bindBg.active = isVisible
    },

    //重写
    //停止动画
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            
            if(cfg.symbol[id].stop_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                }
            }
        }
    },

    //停止回弹之后
    StopMoveEnd(){
        let id = this._id
        if(id === 1){
            let cfg = cc.vv.gameData.getGameCfg()
            if(cfg.symbol[id] && cfg.symbol[id].node){
                this._state = "stop";
                if(this._showNode){
                    this._showNode.active = false
                }
                let aniNode = this.setAnimationToTop(true)
                aniNode.active = true
                for (let i = 0; i < aniNode.children.length; i++) {
                    const element = aniNode.children[i];
                    element.active = false
                }
                let topShowNode = cc.find(cfg.symbol[id].node,aniNode)
                topShowNode.active = true
                aniNode.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
            }
        }
    },
    // update (dt) {},
});
